        .cs-trust-item .cs-trust-label {
            font-size: 13px;
            color: #555;
            font-weight: 500;
            letter-spacing: 0.3px;
        }
        @media (max-width: 768px) {
            .cs-trust-grid { grid-template-columns: repeat(2, 1fr); gap: 18px; }
            .cs-trust-item .cs-trust-num { font-size: 24px; }
        }

        .cs-filter-bar {
            display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 10px;
            margin: 0 0 40px;
            padding: 0;
