        }
        .cs-filter-btn.is-active {
            background: var(--color-primary);
            color: #fff;
            border-color: var(--color-primary);
        }
        .case-study-card.is-hidden { display: none; }

        /* ============ Persona selector (D2C vs B2B) ============ */
        .cs-persona-row {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 14px;
            margin: 0 auto 30px;
